package ncasa.household.application.get;
import java.util.*;import ncasa.household.application.HouseholdNotFoundException;import ncasa.household.application.port.out.HouseholdRepository;import ncasa.household.domain.*;
public final class GetHouseholdStateForExpensePlansUseCase{private final HouseholdRepository households;public GetHouseholdStateForExpensePlansUseCase(HouseholdRepository h){households=h;}public State execute(HouseholdId id){var household=households.findById(id).orElseThrow(HouseholdNotFoundException::new);return new State(household.status()==HouseholdStatus.ACTIVE,household.members().stream().filter(HouseholdMember::isActive).map(m->m.id().value()).collect(java.util.stream.Collectors.toUnmodifiableSet()));}public record State(boolean active,Set<UUID> activeMemberIds){public State{activeMemberIds=Set.copyOf(activeMemberIds);}}}
